-- fx_deal: A booked FX conversion (from an accepted quote)
CREATE TABLE fx_deal (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  fx_quote_id                  uuid NOT NULL REFERENCES fx_quote(id),
  payment_id                   uuid,
  side                         varchar(40) NOT NULL CHECK (side IN ('BUY', 'SELL')),
  sell_currency                char(3) NOT NULL,
  sell_amount                  numeric(28,8) NOT NULL,
  buy_currency                 char(3) NOT NULL,
  buy_amount                   numeric(28,8) NOT NULL,
  rate                         numeric(18,10) NOT NULL,
  value_date                   date NOT NULL,
  journal_entry_id             uuid,
  liquidity_provider           varchar(64),
  status                       varchar(40) NOT NULL DEFAULT 'BOOKED' CHECK (status IN ('BOOKED', 'SETTLED', 'CANCELLED', 'FAILED')),
  cancellation_reason          varchar(255),
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500),
  CONSTRAINT uq_fx_deal_fx_quote_id UNIQUE (tenant_id, fx_quote_id)
);
